<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars($appName, ENT_QUOTES, 'UTF-8') ?> — Organization</title><link rel="stylesheet" href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/assets/app.css"></head>
<body><header class="app-header"><p class="brand">ZPM Registry &amp; GIS</p><div class="user-menu"><span><?= htmlspecialchars($user['full_name'], ENT_QUOTES, 'UTF-8') ?></span></div></header><div class="layout"><?php require __DIR__ . '/partials/nav.php'; ?><main class="main"><h1>Organizational structure</h1><section class="content-card"><h2>Add unit</h2><form class="filter-grid" method="post" action="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/organization/units"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><div class="field"><label for="district_id">District</label><select id="district_id" name="district_id" required><option value="">Select district</option><?php foreach ($districtOptions as $district): ?><option value="<?= (int) $district['id'] ?>"><?= htmlspecialchars($district['name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="field"><label for="name">Unit name</label><input id="name" name="name" required></div><div class="field"><label for="unit_type">Unit type</label><select id="unit_type" name="unit_type"><option value="village">Village</option><option value="locality">Locality</option><option value="other">Other</option></select></div><div class="filter-actions"><button type="submit">Add unit</button></div></form><p class="muted">New units are assigned to the first available block in the selected district. Use approved organizational data for operational records.</p></section><section class="content-card"><h2>District / block / unit register</h2><div class="table-wrap"><table><thead><tr><th>District</th><th>Block</th><th>Unit code</th><th>Unit</th><th>Type</th><th>Individuals</th></tr></thead><tbody><?php foreach ($organizationRows as $row): ?><tr><td><?= htmlspecialchars($row['district_name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['block_name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['unit_code'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['unit_name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars(ucfirst($row['unit_type']), ENT_QUOTES, 'UTF-8') ?></td><td><?= number_format((int) $row['member_count']) ?></td></tr><?php endforeach; ?></tbody></table></div></section></main></div></body></html>
